Given a sorted array arr[] of unique integers, an integer k, and a target value x. Return exactly k elements from the array closest to x, excluding x if it exists.An element a is closer to x than b if:|a - x| < |b - x|, or|a - x| == |b - x| and a > b (i.e., prefer the larger element if tied)Return the k closest elements in order of closeness.Examples: Input: arr[] = [1, 3, 4, 10, 12], k = 2, x = 4Output: [3, 1]Explanation: The value 4 is excluded from consideration.The closest element to 4 is 3 with a distance of 1.The next closest element is 1 with a distance of 3.Input: arr[] = [10, 20, 30, 40, 50], k = 3, x = 25Output: [30, 20, 40]Explanation: First closest element to 25 is 30, Since 30 > 20. Second closest element to 25 is 20.Third closest element to 25 is 40.Try It YourselfTable of Content[Naive Approach] Using Absolute difference and Custom Sorting O(n*log(n)) Time and O(k) Space[Better Approach] Using Linear Search- O(n) time and O(k) space[Expected Approach] Using Binary Search - O(k + log n) time and O(k) space[Naive Approach] Using Absolute difference and Custom Sorting O(n*log(n)) Time and O(k) SpaceThe idea is to use the absolute difference between each element and the target value to measure how close they are. Then, we apply custom sorting: elements with smaller differences come first, and in case of a tie, the larger element is preferred. we take the k element from get from custom sorted array then return it.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

vector<int> findKClosest(vector<int> &arr, int k, int x) {

    // Custom comparator using absolute difference and tie-breaker
    sort(arr.begin(), arr.end(), [x](int a, int b) {
        int diffA = abs(a - x);
        int diffB = abs(b - x);
        // If differences are equal, prefer the larger element
        if (diffA == diffB)
            return a > b;
        return diffA < diffB;
    });

    vector<int> result;
    int count = 0;

    // Pick first k elements which are not equal to x
    for (int num : arr) {
        // skip if element is equal to x
        if (num == x) continue; 
        result.push_back(num);
        count++;
        if (count == k)
            break;
    }

    return result;
}

int main() {
    vector<int> arr = {1, 3, 4, 10, 12};
    int k = 2;
    int x = 4;

    vector<int> closest = findKClosest(arr, k, x);

    for (int num : closest) {
        cout << num << " ";
    }

    return 0;
}


